let lastTimestamp = 0;

/**
 * Returns a Date guaranteed to be strictly greater than any previous Date
 * generated by this process, ensuring sequential audit ledgers maintain
 * strict chronological order even during high-concurrency transactions.
 */
export function getMonotonicDate(): Date {
  let now = Date.now();
  if (now <= lastTimestamp) {
    now = lastTimestamp + 1;
  }
  lastTimestamp = now;
  return new Date(now);
}
